"""Generate a stub file for the constants module."""

from __future__ import annotations

import importlib
import sys
import textwrap
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SRC = ROOT / "src"
sys.path.insert(0, str(SRC))

mod = importlib.import_module("qcconst.constants")

header = textwrap.dedent(
    """\
    # Auto-generated by build_tools/gen_stubs.py - DO NOT EDIT BY HAND
    from collections.abc import Mapping

    from qcconst.models import Value

    class ConstantCollection: ...

    codata: Mapping[int, ConstantCollection]
    constants: ConstantCollection
    phys: ConstantCollection
    """
)
releases = "".join(f"codata{year}: ConstantCollection\n" for year in mod.codata)

uppercase_shims = "\n".join(f"{key}: Value" for key in mod.constants)

stub = Path(mod.__file__).with_suffix(".pyi")  # type: ignore[arg-type]
stub.write_text(header + releases + "\n" + uppercase_shims + "\n", encoding="utf-8")
